{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "Pub/Sub Topic lacks Customer-Managed Encryption Key (CMEK)",
      "resource": "google_pubsub_topic.notification_trigger",
      "severity": "MEDIUM",
      "explanation": "The Pub/Sub topic uses Google-managed encryption keys by default. For enterprise disaster recovery orchestration, using a Customer-Managed Encryption Key (CMEK) provides better control over data security and compliance."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_trigger\" {\n  name = \"enterprise-disaster-recovery-orchestration-platform-topic-notification\"\n\n  kms_key_name = var.kms_key_name\n}\n\nvariable \"kms_key_name\" {\n  description = \"The resource name of the Cloud KMS CryptoKey to be used to protect access message payloads.\"\n  type        = string\n}",
  "fix_summary": "Added a `kms_key_name` attribute to the Pub/Sub topic to enable Customer-Managed Encryption Keys (CMEK). Introduced a corresponding variable `kms_key_name` to allow flexible configuration of the KMS key without hardcoding secrets or specific resource IDs in the module."
}
